    content:
      '# system.irrigate\n\n入口：`const systems = await editor.component.query({type:"FarmingSystem"});` 按身份选取 system。\n调用：await system.irrigate(input, options?)\n优先使用手上水壶，否则在目标旁生成或复用空闲水壶并换拿，不限制AI距离。按规则增加体积含水率百分点；余水分配到连通耕地，全部饱和后流失。回执包含 input/absorbed/distributed/lost，仅表示该次灌水的即时吸收、溢流分配和流失；distributed=0 不排除后续模拟的土壤扩散。effectSummary 分开列出即时灌水和回执中的模拟结算；后续状态须重新读取，不能把读数差异全部归因蒸发。不会立即成熟。 输入 farmId/plotId，无用户可编辑的水量；ok 表示水分事务已提交到当前状态，后台保存状态由宿主管理，演出与落地同步。ACTION_UNAVAILABLE、地形/版本/提交错误拒绝；verify 后检查回执与相关地块含水率。\n\n成功返回 {ok:true, value, context?}；下方 Value 是 result.value 的类型。失败抛出结构化错误。\n\n```ts\ntype Input = { readonly plotId: string; readonly farmId: string; };\ntype Value = CoordinatedFarmingAction & { readonly request: { readonly operation: "irrigate"; readonly input: { readonly plotId: string; readonly farmId: string; }; } & { readonly options?: { commandId?: string | undefined; expectedRevision?: number | undefined; expectedCarriedItemId?: string | undefined; expectedGroundRevision?: number | undefined; } | undefined; }; readonly effectSummary: IrrigationEffectSummary; };\n```\n\n## 返回与输入依赖类型\n```ts\nexport interface CoordinatedFarmingAction {\n    readonly receipt: CommandResult;\n    readonly attempt: FarmingActionAttempt;\n    readonly presentation: {\n        readonly status: "none" | "started" | "cancelled" | "failed";\n        readonly error?: string;\n    };\n}\nexport interface CommandResult {\n    readonly ok: boolean;\n    readonly commandId: string;\n    readonly revision: number;\n    readonly replayed: boolean;\n    readonly changes: readonly FarmChange[];\n    readonly error?: Readonly<{\n        code: FarmingErrorCode;\n        message: string;\n        capacity?: number;\n        used?: number;\n        required?: number;\n    }>;\n}\nexport type FarmChange = {\n    readonly kind: "item-created" | "item-moved" | "item-reused" | "basket-content-changed";\n    readonly itemId: string;\n} | {\n    readonly kind: "carry-changed";\n} | {\n    readonly kind: "basket-unloaded";\n    readonly basketId: string;\n    readonly allocations: readonly {\n        readonly cropId: string;\n        readonly itemId: string;\n        readonly quantity: number;\n        readonly containerId: string;\n        readonly created: boolean;\n    }[];\n} | {\n    readonly kind: "container-created" | "container-content-changed" | "container-removed";\n    readonly containerId: string;\n} | {\n    readonly kind: "container-retention-changed";\n} | {\n    readonly kind: "plot-created" | "plot-updated" | "plot-deleted";\n    readonly plotId: string;\n} | {\n    readonly kind: "plot-ground-changed";\n    readonly plotId: string;\n    readonly ground: PlotGroundState;\n} | (PlotCropChange & {\n    readonly kind: "crop-removed";\n    readonly reason?: "hoe" | "destroyed";\n}) | (PlotCropChange & {\n    readonly kind: "crop-planted";\n    readonly growthUnits: number;\n}) | {\n    readonly kind: "soil-irrigated";\n    readonly water: {\n        readonly input: number;\n        readonly absorbed: number;\n        readonly distributed: number;\n        readonly lost: number;\n    };\n    readonly plotId: string;\n    readonly previousMoistureUnits: number;\n    readonly moistureUnits: number;\n} | {\n    readonly kind: "soil-moisture-changed";\n    readonly plotId: string;\n    readonly previousMoistureUnits: number;\n    readonly moistureUnits: number;\n} | (PlotCropChange & {\n    readonly kind: "crop-growth-applied";\n    readonly previousGrowthUnits: number;\n    readonly growthUnits: number;\n}) | (PlotCropChange & {\n    readonly kind: "crop-stage-changed";\n    readonly previousStageId: string;\n    readonly stageId: string;\n}) | (PlotCropChange & {\n    readonly kind: "crop-matured";\n}) | (PlotCropChange & {\n    readonly kind: "crop-health-changed";\n    readonly source: CropDamageSource;\n    readonly previousHealthPermille: number;\n    readonly healthPermille: number;\n}) | (PlotCropChange & {\n    readonly kind: "crop-harvested";\n    readonly itemId: string;\n    readonly quantity: number;\n}) | {\n    readonly kind: "inventory-changed";\n    readonly itemId: string;\n    readonly previousQuantity: number;\n    readonly quantity: number;\n} | {\n    readonly kind: "simulation-advanced";\n    readonly previousSimulationTimeMs: number;\n    readonly simulatedTimeMs: number;\n    readonly elapsedSystemTimeMs: number;\n    readonly capped: boolean;\n};\nexport interface PlotGroundState {\n    /** Last confirmed E/W/+Z/-Z connectivity, persisted only to bound offline credit. */\n    readonly waterMask?: number;\n    readonly waterSinceMs?: readonly number[];\n    readonly waterCheckedRevision?: number;\n    readonly availability: "available" | "blocked" | "unloaded";\n    readonly reason: GroundBlockReason | null;\n    readonly checkedAtSystemTimeMs: number;\n    readonly groundRevision: number;\n    /** Present after recovery, so the next simulation step cannot credit part of a paused interval. */\n    readonly resumedAtSystemTimeMs?: number;\n}\nexport type GroundBlockReason = "GROUND_MISSING" | "GROUND_ROCK" | "GROUND_TOO_STEEP" | "GROUND_BLOCKED" | "GROUND_UNDERWATER" | "GROUND_UNSUPPORTED";\nexport interface PlotCropChange {\n    readonly plotId: string;\n    readonly cropId: string;\n    readonly cropInstanceId: string;\n}\nexport type CropDamageSource = "pest" | "animal" | "storm" | "wind" | "other";\nexport type FarmingErrorCode = "BASKET_CAPACITY_INSUFFICIENT" | "ITEM_NOT_FOUND" | "ITEM_CHANGED" | "TOOL_REQUIRED" | "NO_ITEM_POSITION" | "NO_STORAGE_SPACE" | "CONTAINER_CAPACITY_INSUFFICIENT" | "INSUFFICIENT_INVENTORY" | GroundBlockReason | "CANCELLED" | "DESTROYED" | "BUSY" | "GROUND_CHANGED" | "PLOT_EXISTS" | "NOT_INITIALIZED" | "INVALID_DEFINITION" | "INVALID_SNAPSHOT" | "INVALID_COMMAND" | "FARM_MISMATCH" | "VERSION_CONFLICT" | "PLOT_NOT_FOUND" | "PLOT_NOT_TILLED" | "PLOT_OCCUPIED" | "CROP_NOT_FOUND" | "CROP_INSTANCE_CHANGED" | "ACTION_UNAVAILABLE" | "CROP_NOT_MATURE" | "STORAGE_FAILURE";\nexport interface FarmingActionAttempt {\n    readonly input: FarmActionInput;\n    readonly options: FarmActionOptions & {\n        readonly commandId: string;\n        readonly expectedRevision: number;\n    };\n}\nexport type FarmActionInput = ActionInput<FarmActionCommand>;\ntype ActionInput<T> = T extends FarmActionCommand ? Omit<T, keyof FarmCommandBase> : never;\n/** Player tool operations. Damage uses a separate public write path; time advancement is test-only. */\nexport type FarmActionCommand = PlantCommand | IrrigateCommand | HarvestCommand | HoeCommand | DeletePlotCommand;\nexport interface PlantCommand extends PlotCommandBase {\n    readonly type: "plant";\n    readonly seedId: string;\n}\nexport interface PlotCommandBase extends FarmCommandBase {\n    readonly plotId: string;\n}\nexport interface FarmCommandBase {\n    readonly commandId: string;\n    readonly farmId: string;\n    readonly expectedRevision: number;\n    readonly expectedGroundRevision?: number;\n    /** Captured by portable item use; guards the unique carrying slot at commit time. */\n    readonly expectedCarriedItemId?: string;\n}\nexport interface IrrigateCommand extends PlotCommandBase {\n    readonly type: "irrigate";\n}\nexport interface HarvestCommand extends PlotCommandBase {\n    readonly type: "harvest";\n    readonly cropInstanceId: string;\n}\nexport interface HoeCommand extends FarmCommandBase {\n    /** Re-tilling removes any occupying crop without yielding inventory. */\n    readonly type: "hoe";\n    readonly target: GroundTarget;\n    /** Bind delayed actions to the observed occupant. null requires empty ground;\n     * omit only for immediate actions protected by the original expectedRevision. */\n    readonly expectedCropInstanceId?: string | null;\n}\nexport interface GroundTarget {\n    readonly groundId: string;\n    readonly cellX: number;\n    readonly cellZ: number;\n}\nexport interface DeletePlotCommand extends PlotCommandBase {\n    readonly type: "delete-plot";\n    readonly cascadeCrop?: boolean;\n}\nexport interface FarmActionOptions {\n    /** Retry with both the original ID and revision, together with the unchanged input. */\n    readonly commandId?: string;\n    readonly expectedRevision?: number;\n    readonly expectedGroundRevision?: number;\n    readonly expectedCarriedItemId?: string;\n}\nexport interface IrrigationEffectSummary {\n    readonly scope: "command-receipt";\n    readonly revision: number;\n    /** Immediate irrigation only. distributed is overflow at application, not later soil transport. */\n    readonly immediateIrrigation: readonly Extract<FarmChange, {\n        kind: "soil-irrigated";\n    }>[];\n    /** Clock settlements included in this receipt; not later observations. */\n    readonly simulationSettlements: readonly Extract<FarmChange, {\n        kind: "simulation-advanced";\n    }>[];\n    readonly laterSoilTransport: "not-observed";\n}\n```\n\n写入选项及完整类型：[完整声明](declare/editor/farming/FarmingSystem.d.ts)。读取若返回 next，按 next.offset 续读。'
